(function(){
  var STYLE_ID = 'kc-current-style';
  var PITCH_IMG = 'data:image/jpeg;base64,';
  var BOBBLE_IMG = 'data:image/png;base64,';

  function injectStyle(){
    if(document.getElementById(STYLE_ID)) return;
    var css = ''
    +'.kc-wrap{max-width:640px;margin:0 auto;}'
    +'.kc-hud{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px;flex-wrap:wrap;}'
    +'.kc-problem{background:#fff;color:#081F2C;font-weight:800;font-size:26px;padding:8px 18px;border-radius:14px;border:3px solid #62CBC9;}'
    +'.kc-timerWrap{flex:1;min-width:90px;max-width:150px;height:14px;background:#0b3346;border-radius:8px;overflow:hidden;border:2px solid #62CBC9;}'
    +'.kc-timerBar{height:100%;background:#CF3339;width:100%;transition:width .1s linear;}'
    +'.kc-round{font-size:14px;color:#081F2C;font-weight:700;}'
    +'.kc-field{position:relative;width:100%;aspect-ratio:900/642;border-radius:16px;overflow:hidden;'
      +'box-shadow:0 6px 18px rgba(0,0,0,.35);background-image:url(\''+PITCH_IMG+'\');background-size:cover;background-position:center;}'
    +'.kc-goalGlow{position:absolute;right:2%;top:30%;width:11%;height:40%;border-radius:8px;pointer-events:none;opacity:0;'
      +'box-shadow:0 0 40px 20px #62CBC9;transition:opacity .3s;}'
    +'.kc-goalGlow.show{opacity:.7;}'
    +'.kc-ball{position:absolute;width:15%;aspect-ratio:1/1;border-radius:50%;display:flex;align-items:center;justify-content:center;'
      +'cursor:pointer;user-select:none;touch-action:manipulation;transition:transform .15s;}'
    +'.kc-ball:active{transform:scale(.92);}'
    +'.kc-ballIcon{font-size:min(9vw,40px);filter:drop-shadow(0 3px 4px rgba(0,0,0,.4));}'
    +'.kc-ballBadge{position:absolute;bottom:-8%;left:50%;transform:translateX(-50%);background:#CF3339;color:#fff;font-weight:800;'
      +'font-size:14px;padding:2px 9px;border-radius:10px;border:2px solid #fff;box-shadow:0 2px 4px rgba(0,0,0,.3);white-space:nowrap;}'
    +'.kc-ball.correctFly{animation:kcFly .55s ease-in forwards;}'
    +'@keyframes kcFly{to{transform:translate(220px,0) scale(.4);opacity:0;}}'
    +'.kc-ball.wrongBonk{animation:kcBonk .4s ease-in-out;}'
    +'@keyframes kcBonk{0%{transform:translate(0,0) rotate(0);}30%{transform:translate(-12px,-5px) rotate(-15deg);}'
      +'60%{transform:translate(7px,4px) rotate(10deg);}100%{transform:translate(0,0) rotate(0);}}'
    +'.kc-flash{position:absolute;right:6%;top:35%;width:20%;aspect-ratio:1/1;border-radius:50%;'
      +'background:radial-gradient(circle,#fff 0%,#62CBC9 60%,transparent 75%);opacity:0;pointer-events:none;}'
    +'.kc-flash.show{animation:kcFlashPop .5s ease-out;}'
    +'@keyframes kcFlashPop{0%{opacity:0;transform:scale(.3);}40%{opacity:1;transform:scale(1.1);}100%{opacity:0;transform:scale(1.4);}}'
    +'.kc-goalText{position:absolute;left:50%;top:8%;transform:translateX(-50%) scale(0);font-size:30px;font-weight:900;color:#CF3339;'
      +'text-shadow:2px 2px 0 #fff,-2px -2px 0 #fff,2px -2px 0 #fff,-2px 2px 0 #fff;pointer-events:none;}'
    +'.kc-goalText.show{animation:kcGoalPop .9s ease-out;}'
    +'@keyframes kcGoalPop{0%{transform:translateX(-50%) scale(0);opacity:0;}25%{transform:translateX(-50%) scale(1.3);opacity:1;}'
      +'45%{transform:translateX(-50%) scale(1);opacity:1;}100%{transform:translateX(-50%) scale(1) translateY(-20px);opacity:0;}}'
    +'.kc-bbImg{width:130px;transform-origin:bottom center;animation:kcBobble 1.1s ease-in-out infinite;'
      +'filter:drop-shadow(0 6px 10px rgba(0,0,0,.3));}'
    +'@keyframes kcBobble{0%,100%{transform:rotate(0deg);}25%{transform:rotate(-6deg);}50%{transform:rotate(0deg);}75%{transform:rotate(6deg);}}'
    +'.kc-revealCard{background:#fff;border-radius:20px;padding:22px 24px;text-align:center;max-width:320px;margin:14px auto 0;'
      +'box-shadow:0 8px 24px rgba(0,0,0,.25);}'
    +'.kc-revealTitle{color:#081F2C;font-weight:900;font-size:17px;margin-top:8px;}'
    +'.kc-revealSub{color:#555;font-size:13px;margin-top:4px;}';
    var s = document.createElement('style');
    s.id = STYLE_ID;
    s.textContent = css;
    document.head.appendChild(s);
  }

  var POSITIONS = [
    {left:'26%', top:'18%'},
    {left:'55%', top:'12%'},
    {left:'28%', top:'55%'},
    {left:'58%', top:'58%'}
  ];

  var TOTAL_ROUNDS = 5;
  var TIME_MS = 6500; // fast clock for the hard tier

  function start(host, ctx){
    injectStyle();
    renderIntro(host, ctx);
  }

  function renderIntro(host, ctx){
    host.innerHTML =
      '<div class="kc-wrap center">'
      + '<p class="h2">Match day at KC Current!</p>'
      + '<p class="sub">Clover needs a sharp shooter. Tap the ball with the right answer before time runs out. Get the shots in fast &mdash; these questions are tough!</p>'
      + '<div class="row mt" style="justify-content:center;">'
      + '  <button class="btn green" id="kcStart">Start the Shootout</button>'
      + '  <button class="btn ghost" id="kcBack">&larr; Map</button>'
      + '</div>'
      + '</div>';
    host.querySelector('#kcStart').addEventListener('click', function(){ startGame(host, ctx); });
    host.querySelector('#kcBack').addEventListener('click', function(){ ctx.close(); });
  }

  function startGame(host, ctx){
    var state = { round: 0, correct: 0, coins: 0 };
    host.innerHTML =
      '<div class="kc-wrap">'
      + '  <div class="kc-hud">'
      + '    <div class="kc-problem" id="kcProblem">?</div>'
      + '    <div class="kc-timerWrap"><div class="kc-timerBar" id="kcTimerBar"></div></div>'
      + '    <div class="kc-round" id="kcRound">Shot 1/'+TOTAL_ROUNDS+'</div>'
      + '  </div>'
      + '  <div class="kc-field" id="kcField">'
      + '    <div class="kc-goalGlow" id="kcGoalGlow"></div>'
      + '    <div class="kc-flash" id="kcFlash"></div>'
      + '    <div class="kc-goalText" id="kcGoalText">GOAL!</div>'
      + '  </div>'
      + '  <div class="fb" id="kcFb">&nbsp;</div>'
      + '</div>';

    var els = {
      problem: host.querySelector('#kcProblem'),
      timerBar: host.querySelector('#kcTimerBar'),
      round: host.querySelector('#kcRound'),
      field: host.querySelector('#kcField'),
      goalGlow: host.querySelector('#kcGoalGlow'),
      flash: host.querySelector('#kcFlash'),
      goalText: host.querySelector('#kcGoalText'),
      fb: host.querySelector('#kcFb')
    };

    var timer = null;
    var locked = false;

    function nextQuestion(){
      if(state.round >= TOTAL_ROUNDS){ return finish(host, ctx, state); }
      state.round++;
      locked = false;
      els.round.textContent = 'Shot ' + state.round + '/' + TOTAL_ROUNDS;
      els.fb.textContent = '\u00A0';
      els.fb.className = 'fb';

      var p = ctx.math.gen('mul', 2);
      els.problem.textContent = p.q + ' = ?';
      var correct = p.a;

      var answers = [correct];
      var guard = 0;
      while(answers.length < 4 && guard < 50){
        guard++;
        var delta = Math.floor(Math.random()*11) - 5; // -5..5
        if(delta === 0) delta = 6;
        var candidate = correct + delta;
        if(candidate > 0 && answers.indexOf(candidate) === -1){
          answers.push(candidate);
        }
      }
      // shuffle
      for(var i = answers.length - 1; i > 0; i--){
        var j = Math.floor(Math.random() * (i+1));
        var tmp = answers[i]; answers[i] = answers[j]; answers[j] = tmp;
      }

      Array.prototype.slice.call(els.field.querySelectorAll('.kc-ball')).forEach(function(b){ b.remove(); });

      answers.forEach(function(val, idx){
        var ball = document.createElement('div');
        ball.className = 'kc-ball';
        ball.style.left = POSITIONS[idx].left;
        ball.style.top = POSITIONS[idx].top;
        ball.innerHTML = '<span class="kc-ballIcon">\u26BD</span><span class="kc-ballBadge">'+val+'</span>';
        ball.addEventListener('pointerup', function(){ handleTap(ball, val, correct); });
        els.field.appendChild(ball);
      });

      var timeLeft = 100;
      els.timerBar.style.width = '100%';
      clearInterval(timer);
      var step = 100 / (TIME_MS/100);
      timer = setInterval(function(){
        timeLeft -= step;
        els.timerBar.style.width = Math.max(timeLeft,0) + '%';
        if(timeLeft <= 0){
          clearInterval(timer);
          if(!locked){
            locked = true;
            els.fb.textContent = 'Time! The answer was ' + correct + '.';
            els.fb.className = 'fb no';
            setTimeout(nextQuestion, 900);
          }
        }
      }, 100);
    }

    function handleTap(ball, val, correct){
      if(locked) return;
      if(val === correct){
        locked = true;
        clearInterval(timer);
        state.correct++;
        state.coins += 2;
        ball.classList.add('correctFly');
        els.goalGlow.classList.add('show');
        els.fb.textContent = 'Goal! Nice shot.';
        els.fb.className = 'fb ok';
        setTimeout(function(){
          els.flash.classList.add('show');
          els.goalText.classList.add('show');
        }, 350);
        setTimeout(function(){
          els.goalGlow.classList.remove('show');
          els.flash.classList.remove('show');
          els.goalText.classList.remove('show');
          nextQuestion();
        }, 1100);
      } else {
        ball.classList.add('wrongBonk');
        els.fb.textContent = 'Not quite \u2014 try another ball!';
        els.fb.className = 'fb no';
        setTimeout(function(){ ball.classList.remove('wrongBonk'); }, 400);
      }
    }

    nextQuestion();
  }

  function finish(host, ctx, state){
    var didWell = state.correct >= 4; // 4 or 5 out of 5
    var firstStar = didWell && !ctx.state.kccurrentStarEarned;

    ctx.award({ coins: state.coins, star: firstStar ? true : false });
    if(firstStar){ ctx.state.kccurrentStarEarned = true; }
    if(ctx.confetti && didWell) ctx.confetti();

    var cloverImg = ctx.clover && ctx.clover.cele ? ctx.clover.cele : '';

    host.innerHTML =
      '<div class="kc-wrap center">'
      + (cloverImg ? '<img src="'+cloverImg+'" alt="Clover" style="width:110px;margin-bottom:8px;">' : '')
      + '<p class="h2">'+ state.correct + ' out of ' + TOTAL_ROUNDS + ' shots!</p>'
      + '<p class="sub">You earned ' + state.coins + ' coins.</p>'
      + (didWell
          ? '<div class="kc-revealCard">'
            + '<img class="kc-bbImg" src="'+BOBBLE_IMG+'" alt="Temwa Chawinga bobblehead">'
            + '<div class="kc-revealTitle">Clover added Temwa Chawinga&rsquo;s bobblehead to her shelf!</div>'
            + '<div class="kc-revealSub">Great shooting today &mdash; see you at the next match.</div>'
            + '</div>'
          : '<p class="sub">Get 4 or more shots in next time to bring home a bobblehead!</p>')
      + '<div class="row mt" style="justify-content:center;">'
      + '  <button class="btn green" id="kcAgain">Play Again</button>'
      + '  <button class="btn ghost" id="kcDone">&larr; Map</button>'
      + '</div>'
      + '</div>';

    host.querySelector('#kcAgain').addEventListener('click', function(){ startGame(host, ctx); });
    host.querySelector('#kcDone').addEventListener('click', function(){ ctx.close(); });
  }

  window.Stops.register('3E', { name: 'KC Current', start: start });
})();
